// tableFor returns wire pair tables.
func tableFor(l Layer) (ids []uint32, syms []Sym, ok bool) {
	switch l {
	case L228:
		return pairs0ID, pairs0Sym, true
	case L229:
		return pairs2ID, pairs2Sym, true
	case L230:
		return pairs4ID, pairs4Sym, true
	case L231:
		return pairs6ID, pairs6Sym, true
	case L232:
		return pairs8ID, pairs8Sym, true
	case L233:
		return pairs10ID, pairs10Sym, true
	}
	return nil, nil, false
}

// symTable returns sym pair tables.
func symTable(l Layer) (syms []Sym, ids []uint32, ok bool) {
	switch l {
	case L228:
		return pairs1Sym, pairs1ID, true
	case L229:
		return pairs3Sym, pairs3ID, true
	case L230:
		return pairs5Sym, pairs5ID, true
	case L231:
		return pairs7Sym, pairs7ID, true
	case L232:
		return pairs9Sym, pairs9ID, true
	case L233:
		return pairs10Sym, pairs10ID, true
	}
	return nil, nil, false
}

// Ctor returns layer wire id.
func Ctor(l Layer, s Sym) (uint32, bool) {
	syms, ids, ok := symTable(l)
	if !ok {
		return 0, false
	}
	n := sort.Search(len(syms), func(i int) bool { return syms[i] >= s })
	if n < len(syms) && syms[n] == s {
		return ids[n], true
	}
	return 0, false
}

// SymOf returns sym by wire id.
func SymOf(l Layer, id uint32) (Sym, bool) {
	ids, syms, ok := tableFor(l)
	if !ok {
		return 0, false
	}
	n := sort.Search(len(ids), func(i int) bool { return ids[i] >= id })
	if n < len(ids) && ids[n] == id {
		return syms[n], true
	}
	return 0, false
}
